/**
 * Document Rendering Engine - Core Type Definitions & Document AST
 *
 * Designed as a standalone, declarative document model capable of powering
 * resumes, invoices, certificates, reports, and arbitrary vector documents.
 */
type PageSizeName = 'letter' | 'a4' | 'a3' | 'a5' | 'legal' | 'tabloid';
interface PageDimensions {
    width: number;
    height: number;
}
type PageOrientation = 'portrait' | 'landscape';
type CoordinateOrigin = 'top-left' | 'bottom-left';
interface Margins {
    top: number;
    right: number;
    bottom: number;
    left: number;
}
type TextAlign = 'left' | 'center' | 'right' | 'justify';
type FontWeight = 'normal' | 'bold' | 100 | 200 | 300 | 400 | 500 | 600 | 700 | 800 | 900;
type FontStyle = 'normal' | 'italic' | 'oblique';
type ShapeType = 'rectangle' | 'circle' | 'line' | 'arrow' | 'polygon' | 'path';
type ImageMaskShape = 'none' | 'circle' | 'rounded';
type ObjectFit = 'contain' | 'cover' | 'fill' | 'none';
type ElementType = 'text' | 'shape' | 'image' | 'view' | 'table' | 'grid';
interface BaseElement {
    id: string;
    type: ElementType;
    x: number;
    y: number;
    width: number;
    height: number;
    zIndex?: number;
    opacity?: number;
    rotation?: number;
    locked?: boolean;
    pageId?: string;
    minWidth?: number;
    maxWidth?: number;
    minHeight?: number;
    maxHeight?: number;
    pageBreakBefore?: boolean;
    pageBreakAfter?: boolean;
    pageBreakInside?: 'auto' | 'avoid';
    keepWithNext?: boolean;
}
interface TextElement extends BaseElement {
    type: 'text';
    text: string;
    fontSize: number;
    fontFamily?: string;
    fontWeight?: FontWeight;
    fontStyle?: FontStyle;
    color?: string;
    align?: TextAlign;
    lineHeight?: number;
    letterSpacing?: number;
    underline?: boolean;
    strike?: boolean;
    wrap?: boolean;
    maxLines?: number;
}
interface ShapeElement extends BaseElement {
    type: 'shape';
    shapeType: ShapeType;
    fillColor?: string;
    strokeColor?: string;
    strokeWidth?: number;
    borderRadius?: number;
    dashArray?: number[];
    x2?: number;
    y2?: number;
    controlX?: number;
    controlY?: number;
    points?: number[];
    pathData?: string;
}
interface ImageElement extends BaseElement {
    type: 'image';
    src: string | Uint8Array;
    fit?: ObjectFit;
    maskShape?: ImageMaskShape;
    borderRadius?: number;
    tintColor?: string;
}
interface ViewElement extends BaseElement {
    type: 'view';
    backgroundColor?: string;
    borderColor?: string;
    borderWidth?: number;
    borderRadius?: number;
    padding?: number | [number, number] | [number, number, number, number];
    layout?: 'absolute' | 'flex';
    flexDirection?: 'row' | 'column';
    gap?: number;
    justifyContent?: 'start' | 'center' | 'end' | 'space-between' | 'space-around';
    alignItems?: 'start' | 'center' | 'end' | 'stretch';
    children?: DocumentElement[];
}
interface TableCell {
    id?: string;
    content: string | DocumentElement | DocumentElement[];
    width?: number;
    colSpan?: number;
    rowSpan?: number;
    backgroundColor?: string;
    textColor?: string;
    fontSize?: number;
    fontWeight?: FontWeight;
    align?: TextAlign;
    padding?: number | [number, number];
}
interface TableRow {
    id?: string;
    cells: TableCell[];
    height?: number;
    backgroundColor?: string;
    isHeader?: boolean;
}
interface TableElement extends BaseElement {
    type: 'table';
    columns?: (number | string)[];
    header?: TableRow;
    rows: TableRow[];
    repeatHeaderOnNewPage?: boolean;
    borderWidth?: number;
    borderColor?: string;
    cellPadding?: number;
    zebra?: boolean;
    zebraColor?: string;
}
interface GridElement extends BaseElement {
    type: 'grid';
    columns: number | (number | string)[];
    gap?: number | [number, number];
    children: DocumentElement[];
}
type DocumentElement = TextElement | ShapeElement | ImageElement | ViewElement | TableElement | GridElement;
interface PageDefinition {
    id: string;
    width?: number;
    height?: number;
    backgroundColor?: string;
    margins?: Partial<Margins>;
    elements: DocumentElement[];
}
interface DocumentMetadata {
    title?: string;
    author?: string;
    subject?: string;
    keywords?: string[];
    creator?: string;
    producer?: string;
    creationDate?: Date;
    modificationDate?: Date;
}
interface DocumentDefinition {
    id?: string;
    metadata?: DocumentMetadata;
    coordinateOrigin?: CoordinateOrigin;
    defaultPageSize?: PageSizeName | PageDimensions;
    orientation?: PageOrientation;
    pages: PageDefinition[];
}
interface TextRun {
    text: string;
    fontFamily: string;
    isBold: boolean;
    isItalic: boolean;
    fontSize: number;
}
interface WrappedLine {
    text: string;
    width: number;
    runs: TextRun[];
}
interface RenderContext {
    pageWidth: number;
    pageHeight: number;
    coordinateOrigin: CoordinateOrigin;
    scale?: number;
}

export type { BaseElement as B, CoordinateOrigin as C, DocumentDefinition as D, ElementType as E, FontWeight as F, GridElement as G, ImageElement as I, Margins as M, ObjectFit as O, PageSizeName as P, RenderContext as R, ShapeElement as S, TextElement as T, ViewElement as V, WrappedLine as W, DocumentMetadata as a, PageDimensions as b, PageOrientation as c, PageDefinition as d, DocumentElement as e, TableElement as f, FontStyle as g, ImageMaskShape as h, ShapeType as i, TableCell as j, TableRow as k, TextAlign as l, TextRun as m };
